{"styles":{"css":"/* Dodatkowy CSS (Additional CSS) – dostępność i responsywność */
/* WCAG 2.4.7: widoczny fokus – nigdy samo outline: none */
:where(a, button, input, select, textarea, summary):focus-visible {
outline: 3px solid var(--wp--preset--color--contrast, #1a1a1a);
outline-offset: 3px;
}
/* WCAG 2.4.11: element z fokusem nie może chować się pod przyklejonym nagłówkiem */
html { scroll-padding-top: 5.3rem; }
/* WCAG 2.5.8: cel dotykowy min. 24 x 24 px */
.wp-block-navigation-item__content,
.wp-block-social-link a { min-height: 24px; min-width: 24px; padding-block: 0.5rem; }
h1 { font-size: clamp(1.75rem, 1.2rem + 2.5vw, 3rem); }
/* Mobile first: kolumny jedna pod drugą na wąskich ekranach */
@media (max-width: 600px) {
.wp-block-columns { gap: 1rem; }
.wp-block-cover { min-height: 60vh; }
